-- Generated atomic three-set import; additive catalogue data only.
begin;
set local lock_timeout='5s';
lock table public.catalogue_sets,public.catalogue_subsets,public.catalogue_cards,public.catalogue_variants,public.catalogue_parallel_rules,public.catalogue_sources in share row exclusive mode;
create temporary table before_catalogue_sets on commit drop as select to_jsonb(t) as row from public.catalogue_sets t;
create temporary table before_catalogue_subsets on commit drop as select to_jsonb(t) as row from public.catalogue_subsets t;
create temporary table before_catalogue_cards on commit drop as select to_jsonb(t) as row from public.catalogue_cards t;
