 if (select count(*) from public.catalogue_sets) not in (45,46)
 or (select count(*) from public.catalogue_cards) not in (22215,22731)
 or ((select count(*) from public.catalogue_sets)=46 and (select count(*) from public.catalogue_sets where id in ('2024-panini-prizm-wwe'))<>1)
