do $$ begin
 if exists(select 1 from public.catalogue_sets t join desired_catalogue_sets e on t.id=e.id where t.id is distinct from e.id or t.name is distinct from e.name or t.short_name is distinct from e.short_name or t.year is distinct from e.year or t.manufacturer is distinct from e.manufacturer or t.release_date is distinct from e.release_date or t.source_file is distinct from e.source_file or t.accent is distinct from e.accent or t.card_count is distinct from e.card_count or t.subset_count is distinct from e.subset_count or t.variant_count is distinct from e.variant_count)
